const jget=(k,d)=>{try{return JSON.parse(LSget(k))||d}catch(e){return d}};
const esc=s=>String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const qa=s=>String(s==null?'':s).replace(/"/g,'&quot;');
try{const a=JSON.parse(LSget('ndm:acc')||'null');if(a&&a.length){ACC.length=0;a.forEach(x=>ACC.push(x))}}catch(e){}
ACC.forEach(a=>{if(a.ed===undefined)a.ed=isAdm(a.u)});
const saveAcc=()=>{if(PERM)ACC.forEach(a=>{if(inInst(a)&&PERM[a.u])a.perm=PERM[a.u].slice()});return LSset('ndm:acc',JSON.stringify(ACC))};
const CE=()=>isAdm(S.user)||!!(ACC.find(a=>a.u===S.user&&inInst(a))||{}).ed;
loadPerm=function(){const lp=jget('ndm:perms',null),valid=l=>l.filter(k=>ALLK().includes(k));PERM={};ACC.filter(inInst).forEach(a=>{let l=Array.isArray(a.perm)?valid(a.perm):(lp&&Array.isArray(lp[a.u])?valid(lp[a.u]):(isAdm(a.u)?ALLK():ALLK().slice(0,3)));if(isAdm(a.u)&&!l.includes('config'))l=l.concat('config');PERM[a.u]=l.length?l:[ALLK()[0]]})};
